// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait PowerManagementAssessmentOwner_Api {
  def id: Art.BridgeId
  def power_evidence_Id : Art.PortId
  def power_assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var power_assessment: Power_Propulsion_Availability_Supervisor.PowerAssessment.Type = $

  def put_power_assessment(value : Power_Propulsion_Availability_Supervisor.PowerAssessment.Type) : Unit = {
    Contract(
      Modifies(power_assessment),
      Ensures(
        power_assessment == value
      )
    )
    Spec {
      power_assessment = value
    }

    Art.putValue(power_assessment_Id, Power_Propulsion_Availability_Supervisor.PowerAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class PowerManagementAssessmentOwner_Initialization_Api (
  val id: Art.BridgeId,
  val power_evidence_Id : Art.PortId,
  val power_assessment_Id : Art.PortId) extends PowerManagementAssessmentOwner_Api

@datatype class PowerManagementAssessmentOwner_Operational_Api (
  val id: Art.BridgeId,
  val power_evidence_Id : Art.PortId,
  val power_assessment_Id : Art.PortId) extends PowerManagementAssessmentOwner_Api {

  // Logika spec var representing port state for incoming data port
  @spec var power_evidence: Power_Propulsion_Availability_Supervisor.PowerEvidence = $

  def get_power_evidence() : Option[Power_Propulsion_Availability_Supervisor.PowerEvidence] = {
    Contract(
      Ensures(
        Res == Some(power_evidence)
      )
    )
    val value : Option[Power_Propulsion_Availability_Supervisor.PowerEvidence] = Art.getValue(power_evidence_Id) match {
      case Some(Power_Propulsion_Availability_Supervisor.PowerEvidence_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port power_evidence.  Expecting 'Power_Propulsion_Availability_Supervisor.PowerEvidence_Payload' but received ${v}")
        None[Power_Propulsion_Availability_Supervisor.PowerEvidence]()
      case _ => None[Power_Propulsion_Availability_Supervisor.PowerEvidence]()
    }
    return value
  }
}
